package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Grade;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Rollup rollup;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, Rollup rollup, Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's rates in grade order, then by from-date; a grade with no rate is left out. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdInOrder(sheetId);
    }

    /** The grade's rate in force on a date: the one with the latest from-date on or before it, or
     *  null when the date is before every rate the grade has or after that rate's to-date. */
    @Transactional(readOnly = true)
    public Rate inForce(String sheetId, Grade grade, LocalDate date) {
        return Rate.inForce(rates.findForGrade(sheetId, grade), date);
    }

    /** Set the sheet's rate for a grade from a from-date (none: from the beginning of time) through
     *  a to-date (none: until the grade's next rate), replacing the rate it had for that from-date. A
     *  to-date before the from-date is refused. */
    @Transactional
    public Rate set(String sheetId, String user, Grade grade, LocalDate from, LocalDate to, BigDecimal pct) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
        }
        sheets.load(sheetId);
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = (from == null ? rates.findFromStart(sheetId, grade) : rates.findFrom(sheetId, grade, from))
                .orElse(null);
        if (rate == null) {
            rate = new Rate(sheetId, grade, from, to, pct);
        } else {
            rate.setPct(pct);
            rate.setTo(to);
        }
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
        } catch (DataIntegrityViolationException raced) {
            // Another user set the same grade's rate for that from-date at the same moment.
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The rate was changed by someone else.");
        }
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + saved.getGrade()
                + " rate=" + saved.getPct().toPlainString() + (from == null ? "" : " from=" + from)
                + (to == null ? "" : " to=" + to));
        rollup.recordChanges(user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.person.Grade;

/** One of the sheet's rates for a grade: a percent with two decimals, in force from its from-date
 *  (or from the beginning of time, when it has none) until the grade's next rate, and no later than
 *  its to-date when it has one. */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Enumerated(EnumType.STRING)
    @Column(name = "grade", nullable = false)
    private Grade grade;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;

    protected Rate() {
    }

    public Rate(String sheetId, Grade grade, LocalDate from, LocalDate to, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        this.to = to;
        setPct(pct);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Grade getGrade() {
        return grade;
    }

    /** The date the rate is in force from, or null when it applies from the beginning of time. */
    public LocalDate getFrom() {
        return from;
    }

    /** The last date the rate is in force, or null when it runs until the grade's next rate. */
    public LocalDate getTo() {
        return to;
    }

    public void setTo(LocalDate to) {
        this.to = to;
    }

    public BigDecimal getPct() {
        return pct;
    }

    /** Change the percent; it is kept to two decimals. */
    public void setPct(BigDecimal pct) {
        this.pct = pct.setScale(2);
    }

    /** Whether the rate is in force on or before this date. */
    public boolean appliesBy(LocalDate date) {
        return from == null || !from.isAfter(date);
    }

    /** Whether the rate's to-date has passed by this date. */
    public boolean endedBy(LocalDate date) {
        return to != null && to.isBefore(date);
    }

    /** Of one grade's rates (from the start first, then by from-date), the one in force on the date:
     *  the one with the latest from-date on or before it, unless its to-date has passed; null when none is. */
    public static Rate inForce(Iterable<Rate> gradeRates, LocalDate date) {
        Rate inForce = null;
        for (Rate rate : gradeRates) {
            if (rate.appliesBy(date)) inForce = rate;
        }
        return inForce == null || inForce.endedBy(date) ? null : inForce;
    }
}
package net.officefloor.hq.app.sheet;

import java.time.Instant;
import java.time.LocalDate;
import net.officefloor.hq.app.rollup.Rollup;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Rollup rollup;

    public SheetService(SheetRepository sheets, Rollup rollup) {
        this.sheets = sheets;
        this.rollup = rollup;
    }

    /** The sheet with this id, as the store holds it now; a sheet never loaded before starts empty. */
    @Transactional
    public Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> create(id));
    }

    /**
     * The sheet's today. Every decision that depends on the date, and every default date, uses this
     * and never the real clock.
     */
    @Transactional
    public LocalDate today(String id) {
        return load(id).getToday();
    }

    /** Change the sheet's today; it has no audit line of its own, only the figures it moves. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id);
        Rollup.Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        rollup.recordChanges(user, before);
        return saved;
    }

    /**
     * The sheet's next claim number: 1 for its first opened claim, then 2, and so on. The sheet stays
     * locked until the transaction ends, so two claims opened at once never share a number.
     */
    @Transactional
    public int nextClaimNumber(String id) {
        load(id);
        sheets.takeClaimNumber(id);
        return sheets.claimNumbersUsed(id);
    }

    /**
     * The next number of one of the sheet's per-period sequences (by key): 1 for its first, then 2,
     * and so on. The sheet stays locked until the transaction ends, so two claims opened at once
     * never share a number.
     */
    @Transactional
    public int nextSequenceNumber(String id, String key) {
        load(id);
        sheets.findForUpdate(id);
        Integer used = sheets.sequenceNumbersUsed(id, key);
        if (used == null) {
            sheets.startSequence(id, key);
            return 1;
        }
        sheets.takeSequenceNumber(id, key);
        return used + 1;
    }

    private Sheet create(String id) {
        try {
            // The only use of the real clock: a new sheet's today starts as the real date.
            return sheets.saveAndFlush(new Sheet(id, Instant.now(), LocalDate.now()));
        } catch (DataIntegrityViolationException raced) {
            // Another user loaded the same new id at the same moment.
            return sheets.findById(id).orElseThrow(() -> raced);
        }
    }
}

